import subprocess, json, os, sys, itertools
def run_once(args, env):
    result = subprocess.run([sys.executable, "train.py"] + args, env=env, capture_output=True, text=True)
    out = result.stdout.strip()
    try:
        return json.loads(out)["test_accuracy"]
    except:
        return None

param_grid = {
    "normalize": ["none", "zscore", "minmax"],
    "lr_schedule": ["const", "step", "cosine"],
    "class_weight": ["none", "balanced"],
    "weight_decay": [0.0, 0.001],
    "batch_size": [32, 64],
    "lr": [0.05, 0.01],
    "epochs": [15, 30],
}
keys = list(param_grid.keys())
best_acc = 0
best_cfg = {}
best_median = 0
# limit combos
import random
samples = 20
for _ in range(samples):
    cfg = {k: random.choice(param_grid[k]) for k in keys}
    # compute median over 5 tags
    accs = []
    for i in range(5):
        tag = f"{i:06x}"
        env = os.environ.copy()
        env["RUN_TAG"] = tag
        args = []
        for k, v in cfg.items():
            if k == "weight_decay":
                args.extend(["--weight_decay", str(v)])
            elif k == "batch_size":
                args.extend(["--batch_size", str(v)])
            elif k == "lr":
                args.extend(["--lr", str(v)])
            elif k == "epochs":
                args.extend(["--epochs", str(v)])
            else:
                args.extend([f"--{k}", str(v)])
        args.extend(["--n", "1200", "--positive_rate", "0.3", "--label_noise", "0.05", "--split", "0.8", "--threshold", "0.5", "--data_seed", "7", "--out", "/tmp/tmp.json"])
        acc = run_once(args, env)
        if acc is not None:
            accs.append(acc)
    if accs:
        accs.sort()
        median = accs[len(accs)//2] if len(accs)%2==1 else (accs[len(accs)//2-1]+accs[len(accs)//2])/2
        if median > best_median:
            best_median = median
            best_cfg = cfg.copy()
            best_acc = median
print("Best median test accuracy:", best_median)
print("Config:", best_cfg)
EOF"}

